//! Hash state is an opaque single owner; methods retain ordinary checked access.
use super::*;
impl Analyzer{pub(super) fn crypto_call(&mut self,context:&mut Context,expression:&mut Expr,loans:&Loans,expected:Option<Type>)->Result<Option<Type>,Diagnostic>{let ExprKind::Call(callee,args)=&expression.kind else{return Ok(None)};let ExprKind::Field(receiver,name)=&callee.kind else{return Ok(None)};let Some(Type::Record(record))=self.expression_type_hint(context,receiver)else{return Ok(None)};if self.program.records[record].native_type!=Some(crate::native_signatures::NativeTypeId::CryptoHasher){return Ok(None);}let operation=match name.as_str(){"update"=>"__update","finalize"=>"__finalize",_=>return Ok(None)};let span=expression.span;let mut arguments=vec![(**receiver).clone()];arguments.extend(args.iter().cloned());expression.kind=ExprKind::Call(Box::new(Expr::new(ExprKind::Name(format!("@native:std:crypto#{operation}")),span)),arguments);self.expression(context,expression,Mode::Consume,loans,expected).map(Some)}}
